// Point module: Payment Outcomes

export type PaymentOutcome = { kind: "Succeeded"; chargeId: string } | { kind: "Failed"; message: string };

export function paymentOutcomeForAmountLabel(amountCents: number): PaymentOutcome {
  if (amountCents <= 0) {
    return { kind: "Failed", message: "Amount must be positive" };
  }
  return { kind: "Succeeded", chargeId: "ch_demo" };
}

export async function chargeCardOutcome(amountCents: number): Promise<PaymentOutcome> {
  return paymentOutcomeForAmountLabel(amountCents);
}

export function outcomeMessageLabel(outcome: PaymentOutcome): string {
  if (outcome.kind == "Succeeded") {
    return ("Paid " + outcome.chargeId);
  }
  if (outcome.kind == "Failed") {
    return outcome.message;
  }
}
